def compare(A,B,d,color):
 inter=union=missing=extras=tailmiss=0; mism=[]
 for r,(a,b) in enumerate(zip(A,B)):
  S={c+d for c,x in enumerate(a) if x==color and 0<=c+d<len(b)}
  T={c for c,x in enumerate(b) if x==color}
  inter+=len(S&T); union+=len(S|T)
  miss=S-T; extra=T-S
  missing+=len(miss); extras+=len(extra)
  last=max(T) if T else -1
  tailmiss+=sum(c>last for c in miss)
  mism.append((sorted(miss),sorted(extra),last))
 return inter,union,missing,extras,tailmiss,mism
