def valid_candidates(A,B,fg):
 W=len(A[0]); cand=[]
 for d in range(-W+1,W):
  S=[{c+d for c,x in enumerate(row) if x==fg and 0<=c+d<W} for row in A]
  T=[{c for c,x in enumerate(row) if x==fg} for row in B]
  miss=[s-t for s,t in zip(S,T)]
  ok=all(not m or min(m)>max(t) for m,t in zip(miss,T))
  inter=sum(len(s&t) for s,t in zip(S,T)); union=sum(len(s|t) for s,t in zip(S,T))
  if ok and sum(map(len,miss)):
   cand.append((inter/union,d, sum(map(len,miss)),sum(map(len,T)), sum(map(len,S)),miss))
 return sorted(cand,reverse=True)
